<?php
require_once __DIR__.'/core/bootstrap.php';$user=require_login($pdo);
if(request_method('POST')){verify_csrf();$action=(string)($_POST['action']??'');try{if($action==='create_contest'){if($user['role']!=='admin')throw new RuntimeException('Only administrators can create scheduled contests.');$name=trim((string)$_POST['name']);$starts=trim((string)$_POST['starts_at']);$problemIds=array_values(array_filter((array)($_POST['problems']??[])));if($name===''||$starts===''||!$problemIds)throw new RuntimeException('Contest name, start time, and at least one problem are required.');$id=generate_id('c');$pdo->beginTransaction();$pdo->prepare("INSERT INTO contests(id,name,type,starts_at,status,created_by) VALUES(:id,:n,'Local',:s,'Upcoming',:u)")->execute(['id'=>$id,'n'=>$name,'s'=>str_replace('T',' ',$starts).':00','u'=>$user['id']]);$cp=$pdo->prepare('INSERT INTO contest_problems(contest_id,problem_id,points) VALUES(:c,:p,:pts)');foreach($problemIds as $i=>$pid)$cp->execute(['c'=>$id,'p'=>$pid,'pts'=>100+(100*$i)]);$pdo->commit();flash('success','Contest created.');redirect('contest_view.php?id='.urlencode($id));}elseif($action==='duel'){$rival=trim((string)$_POST['rival']);$problem=trim((string)$_POST['problem']);if($rival===''||$rival===$user['id']||$problem==='')throw new RuntimeException('Choose a valid rival and problem.');$check=$pdo->prepare('SELECT username FROM users WHERE id=:id');$check->execute(['id'=>$rival]);$rv=$check->fetch();if(!$rv)throw new RuntimeException('Rival not found.');$id=generate_id('duel');$pdo->beginTransaction();$pdo->prepare("INSERT INTO contests(id,name,type,starts_at,status,created_by) VALUES(:id,:n,'Duel',NOW(),'Active',:u)")->execute(['id'=>$id,'n'=>$user['username'].' vs '.$rv['username'],'u'=>$user['id']]);$pdo->prepare('INSERT INTO contest_problems(contest_id,problem_id,points) VALUES(:c,:p,500)')->execute(['c'=>$id,'p'=>$problem]);$j=$pdo->prepare('INSERT INTO contest_participants(contest_id,user_id,score) VALUES(:c,:u,0)');$j->execute(['c'=>$id,'u'=>$user['id']]);$j->execute(['c'=>$id,'u'=>$rival]);$pdo->commit();redirect('contest_view.php?id='.urlencode($id));}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('contests.php');}}
$contests=$pdo->query("SELECT c.*,u.username creator,(SELECT COUNT(*) FROM contest_participants cp WHERE cp.contest_id=c.id) participants FROM contests c LEFT JOIN users u ON u.id=c.created_by ORDER BY c.starts_at DESC")->fetchAll();$problems=$pdo->query('SELECT id,title,difficulty FROM problems ORDER BY title')->fetchAll();$rivals=$pdo->prepare("SELECT id,username,rating FROM users WHERE id<>:u AND role='user' ORDER BY rating DESC");$rivals->execute(['u'=>$user['id']]);$pageTitle='Contests';include __DIR__.'/includes/header.php';?>
<div class="page-head"><div><div class="eyebrow">Competitive Rounds</div><h1>Contests</h1><p>Scheduled rounds, participant tracking, problem sets, scores, and quick head-to-head duel creation.</p></div></div>
<div class="grid grid-2" style="margin-bottom:18px"><div class="card card-pad feature-card"><div class="card-head"><h3><i class="bi bi-lightning-charge text-cyan"></i> Quick Duel</h3><span class="pill pill-easy">LIVE</span></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="duel"><div class="form-grid"><div><label class="form-label">Rival</label><select class="form-select" name="rival" required><?php foreach($rivals->fetchAll() as $r):?><option value="<?=e($r['id'])?>"><?=e($r['username'])?> · <?=(int)$r['rating']?></option><?php endforeach;?></select></div><div><label class="form-label">Problem</label><select class="form-select" name="problem" required><?php foreach($problems as $p):?><option value="<?=e($p['id'])?>"><?=e($p['title'])?> · <?=e($p['difficulty'])?></option><?php endforeach;?></select></div></div><button class="btn btn-primary" style="margin-top:12px">Create duel</button></form></div>
<?php if($user['role']==='admin'):?><div class="card card-pad"><div class="card-head"><h3>Create local contest</h3><span class="pill pill-neutral">ADMIN</span></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create_contest"><div class="form-grid"><div><label class="form-label">Name</label><input class="form-control" name="name" required></div><div><label class="form-label">Start</label><input class="form-control" type="datetime-local" name="starts_at" required></div><div style="grid-column:1/-1"><label class="form-label">Problems (Ctrl+click for multiple)</label><select class="form-select" name="problems[]" multiple size="4" required><?php foreach($problems as $p):?><option value="<?=e($p['id'])?>"><?=e($p['title'])?></option><?php endforeach;?></select></div></div><button class="btn btn-success" style="margin-top:12px">Create contest</button></form></div><?php else:?><div class="card card-pad"><h3>Structured contest model</h3><p class="muted">Contests connect to problems and participants through junction tables, enabling M:N relationships, points, and leaderboard scores.</p><a class="btn btn-secondary" href="how_it_works.php">See architecture</a></div><?php endif;?></div>
<div class="card table-wrap"><table class="data-table"><thead><tr><th>Contest</th><th>Type</th><th>Starts</th><th>Participants</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($contests as $c):?><tr><td><strong><?=e($c['name'])?></strong><br><small class="muted">by <?=e($c['creator']??'System')?></small></td><td><?=e($c['type'])?></td><td><?=e($c['starts_at'])?></td><td><?=(int)$c['participants']?></td><td><span class="pill <?=$c['status']==='Active'?'pill-easy':($c['status']==='Upcoming'?'pill-medium':'pill-neutral')?>"><?=e($c['status'])?></span></td><td><a class="btn btn-sm btn-secondary" href="contest_view.php?id=<?=e($c['id'])?>">View</a></td></tr><?php endforeach;?></tbody></table></div>
<?php include __DIR__.'/includes/footer.php';?>
